import pandas as pd
import numpy as np

TARGET_COLUMN = 'target'

def gini_impurity(y):
    if len(y) == 0:
        return 0.0
    p = np.mean(y)
    return 2 * p * (1 - p)

def best_split(X, y, feature_idx):
    values = np.sort(np.unique(X[:, feature_idx]))
    best_gini = float('inf')
    best_thresh = None
    for i in range(len(values) - 1):
        thresh = (values[i] + values[i + 1]) / 2.0
        left_mask = X[:, feature_idx] <= thresh
        right_mask = ~left_mask
        n_left = np.sum(left_mask)
        n_right = np.sum(right_mask)
        if n_left == 0 or n_right == 0:
            continue
        g = (n_left * gini_impurity(y[left_mask]) + n_right * gini_impurity(y[right_mask])) / len(y)
        if g < best_gini:
            best_gini = g
            best_thresh = thresh
    return best_thresh, best_gini

class DecisionTree:
    def __init__(self, max_depth=3, min_samples_leaf=5, max_features=None, rng=None):
        self.max_depth = max_depth
        self.min_samples_leaf = min_samples_leaf
        self.max_features = max_features
        self.rng = rng or np.random.RandomState(42)
        self.tree = None
    def fit(self, X, y):
        self.tree = self._build(X, y, depth=0)
    def _build(self, X, y, depth):
        if depth >= self.max_depth or len(y) < 2 * self.min_samples_leaf or len(np.unique(y)) == 1:
            return {'leaf': True, 'value': int(np.round(np.mean(y)))}
        n_features = X.shape[1]
        if self.max_features:
            candidates = self.rng.choice(n_features, min(self.max_features, n_features), replace=False)
        else:
            candidates = np.arange(n_features)
        best_feat = None
        best_thresh = None
        best_gini = float('inf')
        for f in candidates:
            thresh, gini = best_split(X, y, f)
            if thresh is not None and gini < best_gini:
                best_gini = gini
                best_feat = f
                best_thresh = thresh
        if best_feat is None:
            return {'leaf': True, 'value': int(np.round(np.mean(y)))}
        left_mask = X[:, best_feat] <= best_thresh
        right_mask = ~left_mask
        if np.sum(left_mask) < self.min_samples_leaf or np.sum(right_mask) < self.min_samples_leaf:
            return {'leaf': True, 'value': int(np.round(np.mean(y)))}
        return {
            'leaf': False, 'feature': best_feat, 'threshold': best_thresh,
            'left': self._build(X[left_mask], y[left_mask], depth + 1),
            'right': self._build(X[right_mask], y[right_mask], depth + 1),
        }
    def predict_one(self, x, node=None):
        if node is None: node = self.tree
        if node['leaf']: return node['value']
        if x[node['feature']] <= node['threshold']:
            return self.predict_one(x, node['left'])
        return self.predict_one(x, node['right'])
    def predict(self, X):
        return np.array([self.predict_one(X[i]) for i in range(len(X))])

