def best_split(X, y, feature_idx):
    """Find best split threshold for a feature."""
    values = np.sort(np.unique(X[:, feature_idx]))
    best_gini = float('inf')
    best_thresh = None
    for i in range(len(values) - 1):
        thresh = (values[i] + values[i + 1]) / 2.0
        left_mask = X[:, feature_idx] <= thresh
        right_mask = ~left_mask
        n_left = np.sum(left_mask)
        n_right = np.sum(right_mask)
        if n_left == 0 or n_right == 0:
            continue
        g = (n_left * gini_impurity(y[left_mask]) + n_right * gini_impurity(y[right_mask])) / len(y)
        if g < best_gini:
