def top_features(Xtr, ytr, m):
    x0 = Xtr[ytr == 0]
    x1 = Xtr[ytr == 1]
    score = np.abs(x1.mean(0) - x0.mean(0)) / np.sqrt(x1.var(0) + x0.var(0) + 1e-9)
    idx = np.argsort(score)[-m:]
    return np.sort(idx)

def knn(Xtr, ytr, Xte, k=15, m=None, weighted=False):
    if m is not None:
        idx = top_features(Xtr, ytr, m)
        Xtr, Xte = Xtr[:, idx], Xte[:, idx]
    Xs, Xt = standardize(Xtr, Xte)
    dists = ((Xt[:,None,:] - Xs[None,:,:]) ** 2).sum(2)
    kk = min(k, len(ytr))
    nbrs = np.argpartition(dists, kth=kk-1, axis=1)[:, :kk]
    preds=[]
    for row, ids in enumerate(nbrs):
        ys = ytr[ids]
        if weighted:
            w = 1/(dists[row, ids] + 1e-9)
            preds.append(int(w[ys==1].sum() > w[ys==0].sum()))
        else:
            preds.append(int(np.bincount(ys, minlength=2).argmax()))
    return np.array(preds)

def ridge(Xtr, ytr, Xte, lam=30, m=20):
    idx = top_features(Xtr, ytr, m)
    Xtr, Xte = Xtr[:, idx], Xte[:, idx]
    Xs, Xt = standardize(Xtr, Xte)
    X1 = np.c_[np.ones(len(Xs)), Xs]
    Xt1 = np.c_[np.ones(len(Xt)), Xt]
    ypm = ytr*2-1
    A = X1.T@X1 + lam*np.eye(X1.shape[1])
    A[0,0] -= lam
    w = np.linalg.solve(A, X1.T@ypm)
    return (Xt1@w > 0).astype(int)

def loocv(names):
    correct=0
    for i in range(len(y)):
        mask=np.ones(len(y),dtype=bool); mask[i]=False
