def gini_from_counts(counts):
    total = counts.sum()
    if total == 0:
        return 0.0
    probs = counts / total
    return 1.0 - np.sum(probs ** 2)

def majority_label(y):
    vals, counts = np.unique(y, return_counts=True)
    return vals[np.argmax(counts)]

def best_split(X, y):
    best = None
    n, p = X.shape
    for j in range(p):
