def standardize(Xtr, Xte):
    mu=Xtr.mean(0); sd=Xtr.std(0); sd[sd<1e-9]=1.0; return (Xtr-mu)/sd, (Xte-mu)/sd

def knn_pred(Xtr,ytr,Xte,k):
    d=((Xte[:,None,:]-Xtr[None,:,:])**2).sum(2)
    idx=np.argpartition(d, kth=min(k-1, len(Xtr)-1), axis=1)[:,:k]
    votes=ytr[idx]
    return (votes.mean(1)>=0.5).astype(int)

def nc_pred(Xtr,ytr,Xte):
    c0=Xtr[ytr==0].mean(0); c1=Xtr[ytr==1].mean(0)
    d0=((Xte-c0)**2).sum(1); d1=((Xte-c1)**2).sum(1)
    return (d1<d0).astype(int)

def gnb_pred(Xtr,ytr,Xte):
    out=[]
    priors=[(ytr==c).mean() for c in [0,1]]
    for c in [0,1]:
        Xc=Xtr[ytr==c]
        mu=Xc.mean(0); var=Xc.var(0)+1e-6
        logp=np.log(priors[c]+1e-12)-0.5*np.log(2*np.pi*var).sum()-0.5*(((Xte-mu)**2)/var).sum(1)
        out.append(logp)
    return (out[1]>out[0]).astype(int)

def lda_pred(Xtr,ytr,Xte,shrink=0.0):
    X0=Xtr[ytr==0]; X1=Xtr[ytr==1]
    mu0=X0.mean(0); mu1=X1.mean(0)
    S0=np.cov(X0,rowvar=False,bias=True); S1=np.cov(X1,rowvar=False,bias=True)
    Sp=((len(X0)*S0)+(len(X1)*S1))/len(Xtr)
    diag=np.diag(np.diag(Sp)); S=(1-shrink)*Sp+shrink*diag+1e-3*np.eye(Xtr.shape[1])
    inv=np.linalg.pinv(S)
    s0=Xte@inv@mu0-0.5*mu0@inv@mu0+np.log((ytr==0).mean()+1e-12)
    s1=Xte@inv@mu1-0.5*mu1@inv@mu1+np.log((ytr==1).mean()+1e-12)
