import pandas as pd, numpy as np
train = pd.read_csv('train.csv')
X = train.drop(columns=['target']).to_numpy(float)
y = train['target'].to_numpy(int)

# deterministic 5-fold stratified split
idx0 = np.where(y==0)[0]
idx1 = np.where(y==1)[0]
folds = [[] for _ in range(5)]
for cls_idx in (idx0, idx1):
    for i, idx in enumerate(cls_idx):
        folds[i % 5].append(idx)
folds = [np.array(f) for f in folds]

def standardize(Xtr, Xte):
    mu = Xtr.mean(0)
    sd = Xtr.std(0)
    sd[sd < 1e-8] = 1.0
    return (Xtr-mu)/sd, (Xte-mu)/sd

def acc(pred, yt):
    return (pred==yt).mean()

def cv(predictor):
    scores=[]
    for fold in folds:
        mask = np.ones(len(y), dtype=bool)
        mask[fold] = False
        Xtr, ytr = X[mask], y[mask]
        Xte, yte = X[~mask], y[~mask]
        scores.append(acc(predictor(Xtr,ytr,Xte), yte))
    return float(np.mean(scores))

def majority(Xtr,ytr,Xte):
    v = int(np.bincount(ytr).argmax())
    return np.full(len(Xte), v)

def nearest_centroid(Xtr,ytr,Xte):
    Xtr2, Xte2 = standardize(Xtr, Xte)
    c0 = Xtr2[ytr==0].mean(0)
    c1 = Xtr2[ytr==1].mean(0)
    d0 = ((Xte2-c0)**2).sum(1)
    d1 = ((Xte2-c1)**2).sum(1)
    return (d1 < d0).astype(int)

def lda(Xtr,ytr,Xte, shrink=1e-1):
    Xtr2, Xte2 = standardize(Xtr, Xte)
    X0 = Xtr2[ytr==0]; X1 = Xtr2[ytr==1]
    m0 = X0.mean(0); m1 = X1.mean(0)
    S0 = np.cov(X0, rowvar=False, bias=True)
    S1 = np.cov(X1, rowvar=False, bias=True)
    S = ((len(X0)*S0)+(len(X1)*S1))/len(Xtr2)
    S = (1-shrink)*S + shrink*np.eye(S.shape[0])
    inv = np.linalg.pinv(S)
    p0 = len(X0)/len(Xtr2); p1 = len(X1)/len(Xtr2)
    s0 = Xte2@inv@m0 - 0.5*m0@inv@m0 + np.log(p0)
    s1 = Xte2@inv@m1 - 0.5*m1@inv@m1 + np.log(p1)
    return (s1 > s0).astype(int)

def diag_nb(Xtr,ytr,Xte, var_smooth=1e-1):
    Xtr2, Xte2 = standardize(Xtr, Xte)
    preds=[]
    for cls in [0,1]:
        Xc = Xtr2[ytr==cls]
        mu = Xc.mean(0)
        var = Xc.var(0) + var_smooth
        logp = -0.5*np.log(2*np.pi*var).sum() -0.5*(((Xte2-mu)**2)/var).sum(1) + np.log(len(Xc)/len(Xtr2))
        preds.append(logp)
    return (preds[1] > preds[0]).astype(int)

def ridge_ls(Xtr,ytr,Xte, lam=1.0):
    Xtr2, Xte2 = standardize(Xtr, Xte)
    Xb = np.c_[np.ones(len(Xtr2)), Xtr2]
    Xt = np.c_[np.ones(len(Xte2)), Xte2]
    y2 = ytr*2-1
    I = np.eye(Xb.shape[1]); I[0,0]=0
    w = np.linalg.pinv(Xb.T@Xb + lam*I) @ Xb.T @ y2
    return (Xt@w > 0).astype(int)

def perceptron(Xtr,ytr,Xte, epochs=20, lr=1.0):
    Xtr2, Xte2 = standardize(Xtr, Xte)
    Xb = np.c_[np.ones(len(Xtr2)), Xtr2]
    Xt = np.c_[np.ones(len(Xte2)), Xte2]
    y2 = ytr*2-1
    w = np.zeros(Xb.shape[1])
    for _ in range(epochs):
        err=0
        for xi, yi in zip(Xb, y2):
            if yi*(xi@w) <= 0:
                w += lr*yi*xi
                err += 1
        if err == 0:
            break
    return (Xt@w > 0).astype(int)

def logistic(Xtr,ytr,Xte, lam=1.0, steps=300, lr=0.1):
    Xtr2, Xte2 = standardize(Xtr, Xte)
    Xb = np.c_[np.ones(len(Xtr2)), Xtr2]
    Xt = np.c_[np.ones(len(Xte2)), Xte2]
    w = np.zeros(Xb.shape[1])
    reg = np.ones_like(w); reg[0]=0
    for _ in range(steps):
        z = Xb@w
        p = 1/(1+np.exp(-np.clip(z,-30,30)))
        grad = Xb.T@(p-ytr)/len(ytr) + lam*reg*w/len(ytr)
