def gini(y):
    if len(y)==0: return 0.0
    p=y.mean(); return 1-p*p-(1-p)*(1-p)

def best_split(X,y):
    best=None
    n,p=X.shape
    base=gini(y)
    for j in range(p):
        order=np.argsort(X[:,j])
        x=X[order,j]; yy=y[order]
        for i in range(1,n):
            if x[i]==x[i-1]:
                continue
            t=(x[i]+x[i-1])/2
            yl=yy[:i]; yr=yy[i:]
            gain=base-(len(yl)/n)*gini(yl)-(len(yr)/n)*gini(yr)
            if best is None or gain>best[0]:
                best=(gain,j,t)
    return best

