rs = np.random.default_rng(0)
perm = rs.permutation(len(y))
folds = np.array_split(perm, 5)

def gini(count1, total):
    if total == 0: return 0.0
    p = count1 / total
    return 1.0 - p*p - (1-p)*(1-p)

def best_split(X, y, min_leaf):
    n, p = X.shape
    total1 = y.sum()
    best = None
    base = gini(total1, n)
    for j in range(p):
        vals = X[:, j]
        order = np.argsort(vals)
        xs = vals[order]
        ys = y[order]
        prefix1 = np.cumsum(ys)[:-1]
        left_n = np.arange(1, n)
        right_n = n - left_n
        valid = (xs[:-1] != xs[1:]) & (left_n >= min_leaf) & (right_n >= min_leaf)
        if not np.any(valid):
            continue
        right1 = total1 - prefix1
        gain = base - (left_n / n) * (1 - (prefix1/left_n)**2 - ((left_n-prefix1)/left_n)**2) - (right_n / n) * (1 - (right1/right_n)**2 - ((right_n-right1)/right_n)**2)
        gain = np.where(valid, gain, -np.inf)
        i = int(np.argmax(gain))
        g = float(gain[i])
        if best is None or g > best[0]:
            best = (g, j, (xs[i] + xs[i+1]) / 2.0)
    return best

def build_tree(X, y, depth, min_leaf):
    pred = int(y.mean() >= 0.5)
    if depth == 0 or len(y) < 2*min_leaf or y.min() == y.max():
        return ("leaf", pred)
    split = best_split(X, y, min_leaf)
    if split is None or split[0] <= 0:
        return ("leaf", pred)
    _, j, thr = split
    mask = X[:, j] <= thr
    return ("node", j, thr, build_tree(X[mask], y[mask], depth-1, min_leaf), build_tree(X[~mask], y[~mask], depth-1, min_leaf))

def predict_one(x, tree):
    while tree[0] == "node":
        _, j, thr, left, right = tree
        tree = left if x[j] <= thr else right
    return tree[1]

def predict(X, tree):
    return np.array([predict_one(x, tree) for x in X], dtype=int)

for depth in [1,2,3,4,5]:
    for min_leaf in [20,50,100,200]:
