import math


integer = int
floating = float


class Array:
    def __init__(self, values):
        self.values = [float(value) for value in values]

    def __iter__(self):
        return iter(self.values)

    def __len__(self):
        return len(self.values)

    def __sub__(self, other):
        other_values = other.values if isinstance(other, Array) else other
        return Array(left - right for left, right in zip(self.values, other_values))

    def __pow__(self, power):
        return Array(value ** power for value in self.values)


def mean(values):
    sequence = values.values if isinstance(values, Array) else list(values)
    if not sequence:
        raise ZeroDivisionError("mean of empty sequence")
    return sum(sequence) / len(sequence)


def sqrt(value):
    return math.sqrt(value)


def isfinite(value):
    return math.isfinite(value)

