import csv
import math


def isna(value):
    return value is None or (isinstance(value, float) and math.isnan(value))


def _parse_value(value):
    if value == "":
        return None
    try:
        number = float(value)
    except ValueError:
        return value
    if number.is_integer() and all(token not in value for token in (".", "e", "E")):
        return int(number)
    return number


class Series:
    def __init__(self, values):
        self.values = list(values)

    def __iter__(self):
        return iter(self.values)

    def __len__(self):
        return len(self.values)

    def __getitem__(self, index):
        return self.values[index]

    def map(self, func):
        return Series(func(value) for value in self.values)

    def mean(self):
        if not self.values:
            raise ZeroDivisionError("mean of empty series")
        return sum(self.values) / len(self.values)

    def to_numpy(self, dtype=float):
        import numpy as np

        return np.Array(dtype(value) for value in self.values)

    def __eq__(self, other):
        if isinstance(other, Series):
            return Series(left == right for left, right in zip(self.values, other.values))
        return Series(value == other for value in self.values)


class DataFrame:
    def __init__(self, data):
        self._data = {column: list(values) for column, values in data.items()}
        self.columns = list(self._data)

    def __len__(self):
        if not self.columns:
            return 0
        return len(self._data[self.columns[0]])

    def __getitem__(self, column):
        return Series(self._data[column])

    def to_csv(self, path, index=False):
        with open(path, "w", newline="", encoding="utf-8") as handle:
            writer = csv.writer(handle)
            writer.writerow(self.columns)
            for row_index in range(len(self)):
                writer.writerow([self._data[column][row_index] for column in self.columns])


def read_csv(path):
    with open(path, newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        columns = reader.fieldnames or []
        data = {column: [] for column in columns}
        for row in reader:
            for column in columns:
                data[column].append(_parse_value(row[column]))
    return DataFrame(data)


def to_numeric(values, errors="raise"):
    converted = []
    iterable = values.values if isinstance(values, Series) else values
    for value in iterable:
        try:
            converted.append(float(value))
        except (TypeError, ValueError):
            if errors == "raise":
                raise
            converted.append(None)
    return Series(converted)

