import pandas as pd, numpy as np
train = pd.read_csv('train.csv')
X = train[[c for c in train.columns if c not in ('entity_id','target')]].to_numpy(float)
y = train['target'].to_numpy(float)
g = train['entity_id']


def std_fit(Xtr, Xte):
    mu = Xtr.mean(0)
    sd = Xtr.std(0)
    sd[sd==0]=1
    return (Xtr-mu)/sd, (Xte-mu)/sd

def rmse(a,b):
    return float(np.sqrt(np.mean((a-b)**2)))

def ridge_fit(Xtr,ytr,a):
    D = np.c_[np.ones(len(Xtr)), Xtr]
    P = np.eye(D.shape[1]) * a
    P[0,0]=0
    return np.linalg.solve(D.T@D + P, D.T@ytr)

def ridge_pred(b,Xte):
    return np.c_[np.ones(len(Xte)), Xte] @ b

def grouped_score_ridge(alpha):
    p = np.empty(len(y))
    for group in g.drop_duplicates():
        tr = (g != group).to_numpy()
        te = ~tr
        Ztr, Zte = std_fit(X[tr], X[te])
        b = ridge_fit(Ztr, y[tr], alpha)
        p[te] = ridge_pred(b, Zte)
    return rmse(y,p)

def grouped_score_pcr(k, alpha):
