import csv


TARGET_COLUMN = "target"


def read_dataset(path: str, include_target: bool):
    with open(path, newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        fieldnames = reader.fieldnames or []
        feature_names = [name for name in fieldnames if name != TARGET_COLUMN]
        rows = []
        targets = []
        for row in reader:
            rows.append([float(row[name]) for name in feature_names])
            if include_target:
                targets.append(float(row[TARGET_COLUMN]))
    return feature_names, rows, targets


def fit_scaler(rows):
    n_rows = len(rows)
    n_features = len(rows[0])
    means = [0.0] * n_features
    scales = [0.0] * n_features

    for row in rows:
        for index, value in enumerate(row):
            means[index] += value
    for index in range(n_features):
        means[index] /= n_rows

    for row in rows:
        for index, value in enumerate(row):
            diff = value - means[index]
            scales[index] += diff * diff
    for index in range(n_features):
        scales[index] = (scales[index] / n_rows) ** 0.5
        if scales[index] == 0.0:
            scales[index] = 1.0

    return means, scales


def transform_rows(rows, means, scales):
    transformed = []
    for row in rows:
        transformed.append([(value - means[index]) / scales[index] for index, value in enumerate(row)])
    return transformed


def solve_linear_system(matrix, vector):
    size = len(vector)
    augmented = [matrix[row_index][:] + [vector[row_index]] for row_index in range(size)]

    for pivot_index in range(size):
        best_row = max(range(pivot_index, size), key=lambda row_index: abs(augmented[row_index][pivot_index]))
        augmented[pivot_index], augmented[best_row] = augmented[best_row], augmented[pivot_index]

        pivot = augmented[pivot_index][pivot_index]
        if abs(pivot) < 1e-12:
            pivot = 1e-12
            augmented[pivot_index][pivot_index] = pivot

        for column_index in range(pivot_index, size + 1):
            augmented[pivot_index][column_index] /= pivot

        for row_index in range(size):
            if row_index == pivot_index:
                continue
            factor = augmented[row_index][pivot_index]
            if factor == 0.0:
                continue
            for column_index in range(pivot_index, size + 1):
                augmented[row_index][column_index] -= factor * augmented[pivot_index][column_index]

    return [augmented[row_index][size] for row_index in range(size)]


def fit_ridge_regression(rows, targets, ridge):
    n_features = len(rows[0]) + 1
    gram = [[0.0] * n_features for _ in range(n_features)]
    rhs = [0.0] * n_features

    for row, target in zip(rows, targets):
        design_row = [1.0] + row
        for left_index in range(n_features):
            rhs[left_index] += design_row[left_index] * target
            for right_index in range(n_features):
                gram[left_index][right_index] += design_row[left_index] * design_row[right_index]

    for feature_index in range(1, n_features):
        gram[feature_index][feature_index] += ridge

    return solve_linear_system(gram, rhs)


def predict_rows(rows, coefficients):
    predictions = []
    intercept = coefficients[0]
    weights = coefficients[1:]
    for row in rows:
        prediction = intercept
        for value, weight in zip(row, weights):
            prediction += value * weight
        predictions.append(prediction)
    return predictions


def write_predictions(path: str, predictions):
    with open(path, "w", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow(["prediction"])
        for prediction in predictions:
            writer.writerow([prediction])


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    _, train_rows, train_targets = read_dataset(train_csv, include_target=True)
    _, test_rows, _ = read_dataset(test_csv, include_target=False)

    means, scales = fit_scaler(train_rows)
    train_features = transform_rows(train_rows, means, scales)
    test_features = transform_rows(test_rows, means, scales)

    coefficients = fit_ridge_regression(train_features, train_targets, ridge=0.001)
    predictions = predict_rows(test_features, coefficients)
    write_predictions(output_csv, predictions)

