import csv


TARGET_COLUMN = "target"


def _read_rows(path: str) -> list[dict[str, str]]:
    with open(path, newline="", encoding="utf-8") as handle:
        return list(csv.DictReader(handle))


def _feature_names(rows: list[dict[str, str]]) -> list[str]:
    return [name for name in rows[0] if name != TARGET_COLUMN]


def _matrix(rows: list[dict[str, str]], feature_names: list[str]) -> list[list[float]]:
    return [[float(row[name]) for name in feature_names] for row in rows]


def _standardize(train_matrix: list[list[float]], test_matrix: list[list[float]]) -> tuple[list[list[float]], list[list[float]]]:
    n_rows = len(train_matrix)
    n_features = len(train_matrix[0])
    means = [sum(row[index] for row in train_matrix) / n_rows for index in range(n_features)]
    scales = []
    for index in range(n_features):
        variance = sum((row[index] - means[index]) ** 2 for row in train_matrix) / n_rows
        scales.append(variance ** 0.5 or 1.0)

    def transform(matrix: list[list[float]]) -> list[list[float]]:
        return [
            [(row[index] - means[index]) / scales[index] for index in range(n_features)]
            for row in matrix
        ]

    return transform(train_matrix), transform(test_matrix)


def _squared_distance(left: list[float], right: list[float]) -> float:
    return sum((left_value - right_value) ** 2 for left_value, right_value in zip(left, right))


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    """Predict each test row with the target of its nearest training neighbor."""
    train_rows = _read_rows(train_csv)
    test_rows = _read_rows(test_csv)
    feature_names = _feature_names(train_rows)

    train_matrix = _matrix(train_rows, feature_names)
    test_matrix = _matrix(test_rows, feature_names)
    train_matrix, test_matrix = _standardize(train_matrix, test_matrix)
    train_targets = [float(row[TARGET_COLUMN]) for row in train_rows]

    predictions = []
    for test_row in test_matrix:
        best_index = min(
            range(len(train_matrix)),
            key=lambda index: _squared_distance(test_row, train_matrix[index]),
        )
        predictions.append(train_targets[best_index])

    with open(output_csv, "w", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow(["prediction"])
        writer.writerows([[value] for value in predictions])

