import numpy as np
import pandas as pd

np.random.seed(42)

train = pd.read_csv('train.csv')
test = pd.read_csv('test.csv')

TARGET_COLUMN = 'target'
feature_cols = [c for c in train.columns if c != TARGET_COLUMN]

X_train = train[feature_cols].values.astype(float)
y_train = train[TARGET_COLUMN].values
X_test = test[feature_cols].values.astype(float)
y_test = test[TARGET_COLUMN].values

# Standardize features
mu = X_train.mean(axis=0)
sigma = X_train.std(axis=0)
sigma[sigma == 0] = 1.0
X_train_s = (X_train - mu) / sigma
X_test_s = (X_test - mu) / sigma

# Simple decision tree
def gini(y):
    if len(y) == 0:
        return 0
    p = y.mean()
    return 1 - p**2 - (1-p)**2

class DecisionTree:
    def __init__(self, max_depth=3, min_samples_split=2):
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.tree = None

    def _best_split(self, X, y):
        n, d = X.shape
        best_gini = float('inf')
        best_feat = None
        best_thresh = None

        for j in range(d):
            thresholds = np.unique(X[:, j])
            for thresh in thresholds:
                left_mask = X[:, j] <= thresh
                right_mask = ~left_mask
                if left_mask.sum() < 1 or right_mask.sum() < 1:
                    continue
                g = (left_mask.sum() * gini(y[left_mask]) + right_mask.sum() * gini(y[right_mask])) / n
                if g < best_gini:
                    best_gini = g
                    best_feat = j
                    best_thresh = thresh

        return best_feat, best_thresh, best_gini

    def _build(self, X, y, depth=0):
        n = len(y)
        label = int(y.mean() >= 0.5)

        if depth >= self.max_depth or n < self.min_samples_split or len(np.unique(y)) == 1:
            return {'leaf': True, 'label': label, 'prob': y.mean()}

        feat, thresh, _ = self._best_split(X, y)
        if feat is None:
            return {'leaf': True, 'label': label, 'prob': y.mean()}

        left_mask = X[:, feat] <= thresh
        right_mask = ~left_mask

        return {
            'leaf': False,
            'feat': feat,
            'thresh': thresh,
            'left': self._build(X[left_mask], y[left_mask], depth+1),
            'right': self._build(X[right_mask], y[right_mask], depth+1)
        }

    def fit(self, X, y):
        self.tree = self._build(X, y)
        return self

    def _predict_one(self, node, x):
        if node['leaf']:
            return node['prob']
        if x[node['feat']] <= node['thresh']:
            return self._predict_one(node['left'], x)
        else:
            return self._predict_one(node['right'], x)

    def predict_proba(self, X):
        return np.array([self._predict_one(self.tree, x) for x in X])

print('Decision Tree tests:')
for max_depth in [1, 2, 3, 4, 5]:
    dt = DecisionTree(max_depth=max_depth)
    dt.fit(X_train_s, y_train)
    probs = dt.predict_proba(X_test_s)
    preds = (probs > 0.5).astype(int)
    acc = (preds == y_test).mean()
    print(f'DT depth={max_depth}: {acc:.3f}')
