import pandas as pd

train = pd.read_csv('train.csv')
test = pd.read_csv('test.csv')

y_train = train['target'].values
global_mean = y_train.mean()
test_targets = test['target'].values

# Try decay weights: weight[k] = gamma^k (row 1 = gamma^0 = 1, row 2 = gamma, etc.)
def entity_decay_mean(vals, gamma):
    n = len(vals)
    weights = gamma ** np.arange(n)
    return np.average(vals, weights=weights)

# Try different gammas and lambdas
best_test = {'rmse': float('inf'), 'gamma': None, 'lambda': None}
best_cv = {'rmse': float('inf'), 'gamma': None, 'lambda': None}

for gamma in [0.3, 0.5, 0.6, 0.7, 0.8, 0.9, 1.0]:
    # LFRO CV: predict row 0 using rows[1:] with decay (gamma^0 for row[1], etc.)
    for lam in np.linspace(0.5, 1.0, 51):
        sq_errors = []
        for eid in train['entity_id'].unique():
            rows = train[train['entity_id'] == eid]['target'].values
            if len(rows) < 2:
                continue
            rest = rows[1:]  # rows 2..N in original
            entity_mean_rest = entity_decay_mean(rest, gamma)
            pred = lam * entity_mean_rest + (1 - lam) * global_mean
            sq_errors.append((rows[0] - pred) ** 2)
        cv_rmse = np.sqrt(np.mean(sq_errors))
        if cv_rmse < best_cv['rmse']:
            best_cv = {'rmse': cv_rmse, 'gamma': gamma, 'lambda': lam}

        # Also check test RMSE (for analysis only, not for solution)
        entity_means = {eid: entity_decay_mean(
            train[train['entity_id'] == eid]['target'].values, gamma
        ) for eid in train['entity_id'].unique()}
        preds = lam * test['entity_id'].map(entity_means).fillna(global_mean) + (1-lam)*global_mean
        test_rmse = np.sqrt(np.mean((test_targets - preds.values)**2))
        if test_rmse < best_test['rmse']:
            best_test = {'rmse': test_rmse, 'gamma': gamma, 'lambda': lam}

print(f'CV-best: gamma={best_cv[\"gamma\"]:.2f}, lambda={best_cv[\"lambda\"]:.2f}, cv_rmse={best_cv[\"rmse\"]:.4f}')
# Apply CV-best to test
gamma_cv = best_cv['gamma']
lam_cv = best_cv['lambda']
entity_means_cv = {eid: entity_decay_mean(
    train[train['entity_id'] == eid]['target'].values, gamma_cv
) for eid in train['entity_id'].unique()}
preds_cv = lam_cv * test['entity_id'].map(entity_means_cv).fillna(global_mean) + (1-lam_cv)*global_mean
test_rmse_cv = np.sqrt(np.mean((test_targets - preds_cv.values)**2))
print(f'=> Test RMSE with CV-tuned params: {test_rmse_cv:.4f}')

print()
print(f'Oracle best: gamma={best_test[\"gamma\"]:.2f}, lambda={best_test[\"lambda\"]:.2f}, test_rmse={best_test[\"rmse\"]:.4f}')
